#!/usr/bin/env bash
# INSPECT_UBUNTU_SAMPLES_READONLY.sh
#
# Read-only static inspection of the 10 frozen Linux ransomware samples.
#
# Purpose (DECISIONS.md D-042): derive the per-sample invocation contract (usage
# text, required arguments, target semantics) WITHOUT executing any sample.
# Only file/readelf/strings are used; nothing is executed, no telemetry starts,
# no canary corpus is touched, no campaign slot is consumed.
#
# The sample list is generated by the host from the frozen 40-row manifest and
# transferred as a TSV: run_id <TAB> sha256 <TAB> bytes <TAB> path <TAB> mode_octal.
# Every row is re-verified inside the guest as root (sha256, bytes, mode, mtime)
# before and after inspection.
#
# Samples are root-owned 0400; the helper runs as root via the transferred sudo
# credential on stdin. The password is never in argv.
set -euo pipefail
MODE="${1:-inspect}"; shift || true
if [[ "${1:-}" == "--root" ]]; then shift; ROOT_MODE=1; else ROOT_MODE=0; fi
OUT="${1:-}"; CRED="${2:-}"; LIST="${3:-}"; ARCHIVE="${4:-}"
[[ -n "$OUT" && -n "$CRED" && -n "$LIST" && -n "$ARCHIVE" ]] || { echo "USAGE: $0 inspect OUT CRED LIST ARCHIVE" >&2; exit 64; }

if [[ "$ROOT_MODE" -eq 0 ]]; then
  exec sudo -S -p '' /bin/bash "$0" "$MODE" --root "$OUT" "$CRED" "$LIST" "$ARCHIVE" < "$CRED"
fi

mkdir -p "$OUT/evidence" "$OUT/work"
exec >> "$OUT/work/inspection.log" 2>&1

json_write(){ local path="$1"; shift; python3 - "$path" "$@" <<'PYJ'
import json,sys
p=sys.argv[1]; d={}
for item in sys.argv[2:]:
    k,v=item.split('=',1)
    if v in ('true','false'): v=(v=='true')
    else:
      try:
        if '.' in v: v=float(v)
        else: v=int(v)
      except: pass
    d[k]=v
with open(p,'w',encoding='utf-8') as f: json.dump(d,f,indent=2,sort_keys=True); f.write('\n')
PYJ
}

sha256_file(){ sha256sum "$1" | awk '{print $1}'; }

echo "INSPECTION_START_UTC=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "ROOT_UID=$(id -u) ROOT_USER=$(id -un)"
for t in file readelf strings grep tar; do
  if command -v "$t" >/dev/null 2>&1; then echo "TOOL_PRESENT $t=$(command -v "$t")"; else echo "TOOL_MISSING $t"; fi
done
command -v python3 >/dev/null 2>&1 || { echo "PYTHON3_MISSING" >&2; exit 65; }

HAVE_FILE=0; HAVE_READELF=0; HAVE_STRINGS=0
if command -v file >/dev/null 2>&1; then HAVE_FILE=1; fi
if command -v readelf >/dev/null 2>&1; then HAVE_READELF=1; fi
if command -v strings >/dev/null 2>&1; then HAVE_STRINGS=1; fi
echo "TOOL_STATE file=$HAVE_FILE readelf=$HAVE_READELF strings=$HAVE_STRINGS"

# Pure-Python fallbacks: binutils is not guaranteed on a minimal lab image, and
# the usage text is the critical evidence. Neither fallback executes the sample.
extract_strings(){
  python3 - "$1" <<'PYSTR'
import re,sys
data=open(sys.argv[1],'rb').read()
for m in re.finditer(rb'[\x20-\x7e]{4,}', data):
    sys.stdout.write(m.group(0).decode('latin-1')+'\n')
PYSTR
}

elf_metadata(){
  python3 - "$1" <<'PYELF'
import struct,sys
p=sys.argv[1]
d=open(p,'rb').read(64)
print('--- python elf header (readelf missing) ---')
if d[:4]!=b'\x7fELF':
    print('NOT_ELF')
    raise SystemExit(0)
cls=d[4]; enc=d[5]
end='<' if enc==1 else '>'
e_type=struct.unpack_from(end+'H',d,16)[0]
e_machine=struct.unpack_from(end+'H',d,18)[0]
e_entry=struct.unpack_from(end+('Q' if cls==2 else 'I'),d,24)[0]
e_phoff=struct.unpack_from(end+('Q' if cls==2 else 'I'),d,32)[0]
e_shoff=struct.unpack_from(end+('Q' if cls==2 else 'I'),d,40)[0]
e_phentsize=struct.unpack_from(end+'H',d,54)[0]
e_phnum=struct.unpack_from(end+'H',d,56)[0]
print('Class: %s' % ('ELF64' if cls==2 else 'ELF32'))
print('Data: %s endian' % ('little' if enc==1 else 'big'))
print('Type: %d' % e_type)
print('Machine: %d' % e_machine)
print('Entry point: 0x%x' % e_entry)
print('Program header offset: %d count=%d entsize=%d' % (e_phoff,e_phnum,e_phentsize))
print('Section header offset: %d' % e_shoff)
PYELF
}

count=0
while IFS=$'\t' read -r run_id sha bytes path octal; do
  [[ -z "$run_id" ]] && continue
  [[ "$run_id" =~ ^L-R-[0-9]{2}$ ]] || { echo "BAD_RUN_ID:$run_id" >&2; exit 70; }
  [[ -f "$path" ]] || { echo "SAMPLE_MISSING:$run_id:$path" >&2; exit 71; }

  actual_sha=$(sha256_file "$path")
  actual_bytes=$(stat -c %s "$path")
  mode_norm=$(printf '%o' $((8#$octal)))
  actual_mode=$(stat -c %a "$path")
  mtime_before=$(stat -c %Y "$path")
  size_before=$(stat -c %s "$path")

  [[ "$actual_sha" == "$sha" ]] || { echo "SAMPLE_SHA_MISMATCH:$run_id:$actual_sha" >&2; exit 72; }
  [[ "$actual_bytes" == "$bytes" ]] || { echo "SAMPLE_BYTES_MISMATCH:$run_id:$actual_bytes" >&2; exit 73; }
  [[ "$actual_mode" == "$mode_norm" ]] || { echo "SAMPLE_MODE_MISMATCH:$run_id:${actual_mode}!=${mode_norm}" >&2; exit 74; }

  d="$OUT/evidence/$run_id"
  mkdir -p "$d"

  {
    echo "RUN_ID=$run_id"
    echo "PATH=$path"
    echo "SHA256=$actual_sha"
    echo "BYTES=$actual_bytes"
    echo "MODE=$actual_mode"
    echo "MTIME_EPOCH=$mtime_before"
    echo "INSPECT_UTC=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    echo "--- file ---"
    if [[ "$HAVE_FILE" -eq 1 ]]; then file "$path" 2>&1 || true; else echo "file: TOOL_MISSING"; fi
  } > "$d/binary_metadata.txt"

  if [[ "$HAVE_READELF" -eq 1 ]]; then
    {
      echo "--- readelf -h ---"; readelf -h "$path" 2>&1 || true
      echo "--- readelf -d ---"; readelf -d "$path" 2>&1 || true
      echo "--- readelf -n ---"; readelf -n "$path" 2>&1 || true
      echo "--- readelf -l (program headers) ---"; readelf -l "$path" 2>&1 || true
    } >> "$d/binary_metadata.txt"
    readelf_source=binutils
  else
    elf_metadata "$path" >> "$d/binary_metadata.txt"
    readelf_source=python
  fi

  if [[ "$HAVE_STRINGS" -eq 1 ]]; then
    strings -a -n 4 "$path" > "$d/strings.txt"
    strings_source=binutils
  else
    extract_strings "$path" > "$d/strings.txt"
    strings_source=python
  fi

  # Keep the full strings file (complete evidence) plus a focused hit list.
  grep -a -n -i -E 'password|passwd|usage|option|argument|--[a-z]|-p[[:space:]]|encrypt|decrypt|ransom|note|extension|target|directory|folder|path[[:space:]]*[=:]|help|key|argv' "$d/strings.txt" > "$d/usage_hits.txt" || true

  mtime_after=$(stat -c %Y -- "$path")
  size_after=$(stat -c %s -- "$path")
  [[ "$mtime_before" == "$mtime_after" ]] || { echo "SAMPLE_MTIME_CHANGED:$run_id" >&2; exit 75; }
  [[ "$size_before" == "$size_after" ]] || { echo "SAMPLE_SIZE_CHANGED:$run_id" >&2; exit 76; }

  json_write "$d/inspection_receipt.json" \
    status=PASS run_id="$run_id" sample_sha256="$actual_sha" sample_bytes="$actual_bytes" \
    sample_guest_path="$path" mode_octal="$mode_norm" sample_read_only=true \
    sample_executed=false telemetry_started=false network_used=false host_raw_sample_bytes=false \
    strings_source="$strings_source" readelf_source="$readelf_source" \
    strings_bytes="$(stat -c %s "$d/strings.txt")" strings_sha256="$(sha256_file "$d/strings.txt")" \
    usage_hits_bytes="$(stat -c %s "$d/usage_hits.txt")" \
    binary_metadata_sha256="$(sha256_file "$d/binary_metadata.txt")" \
    inspection_utc="$(date -u +%Y-%m-%dT%H:%M:%SZ)"

  echo "SAMPLE_INSPECTED run_id=$run_id strings_bytes=$(stat -c %s "$d/strings.txt") usage_hits_bytes=$(stat -c %s "$d/usage_hits.txt")"
  count=$((count+1))
done < "$LIST"

[[ "$count" -eq 10 ]] || { echo "SAMPLE_COUNT_MISMATCH:$count!=10" >&2; exit 77; }

json_write "$OUT/evidence/inspection_receipt.json" \
  status=PASS inspection_type=READ_ONLY_STATIC samples_inspected="$count" \
  sample_executed=false telemetry_started=false network_used=false host_raw_sample_bytes=false \
  campaign_slots_consumed=0 sample_list_sha256="$(sha256_file "$LIST")" \
  inspection_utc="$(date -u +%Y-%m-%dT%H:%M:%SZ)"

( cd "$OUT" && find evidence work -type f ! -name 'SHA256SUMS.txt' -print0 | sort -z | xargs -0 sha256sum ) > "$OUT/evidence/SHA256SUMS.txt"
tar -czf "$ARCHIVE" -C "$OUT" evidence work
echo "INSPECTION_COMPLETE_UTC=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "ARCHIVE=$ARCHIVE ARCHIVE_SHA256=$(sha256_file "$ARCHIVE") ARCHIVE_BYTES=$(stat -c %s "$ARCHIVE")"
